        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        self._update_previous_market_values(data)

        required = [self.spy, self.aapl, self.ibm, self.bac, self.aig]
        if any(symbol not in data.Bars for symbol in required):
            return

        if self.IsWarmingUp:
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = float(spy_bar.Close)
        spy_sma = float(self.spy_sma.Current.Value)

        if self.strategy_a_shares == 0:
            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and spy_close > spy_sma
            ):
                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                quantity = int(target_value / spy_close)

                if quantity > 0:
                    ticket = self.MarketOrder(self.spy, quantity)
                    if ticket.Status != OrderStatus.Invalid:
                        self.strategy_a_shares += quantity

        elif (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and spy_close < spy_sma
        ):
            quantity = self.strategy_a_shares
            if quantity > 0:
                self.MarketOrder(self.spy, -quantity)
                self.strategy_a_shares = 0

        if self.strategy_b_shares == 0:
            red_streak = self._aapl_red_streak(data)
            if red_streak >= 3 and self.Portfolio.Cash >= 20000:
                quantity = int(20000 / float(aapl_bar.Close))
                if quantity > 0:
                    ticket = self.MarketOrder(self.aapl, quantity)
                    if ticket.Status != OrderStatus.Invalid:
                        self.strategy_b_shares += quantity

        elif float(self.aapl_rsi.Current.Value) > 60:
            quantity = self.strategy_b_shares
            if quantity > 0:
                self.MarketOrder(self.aapl, -quantity)
                self.strategy_b_shares = 0

    def _update_previous_market_values(self, data):
        if self.spy in data.Bars and self.spy_sma.IsReady:
            self.previous_spy_close = float(data.Bars[self.spy].Close)
            self.previous_spy_sma = float(self.spy_sma.Current.Value)

    def _aapl_red_streak(self, data):
        history = self.History(self.aapl, 4, Resolution.Daily)
        if history.empty:
            return 0

        closes = list(history.loc[self.aapl]["close"])
        if len(closes) < 4:
            return 0

        today_close = float(data.Bars[self.aapl].Close)
        closes.append(today_close)

        streak = 0
        for index in range(len(closes) - 1, 0, -1):
            if closes[index] < closes[index - 1]:
                streak += 1
            else:
                break

        return streak
